list_orders.code:
use WebCommander\Sdk\Resources\Orders\Orders;

$response = Orders::listOrders($client, ['order_status' => 'in_progress', 'payment_status' => 'unpaid', 'limit' => 10]);

foreach ($response->map['orders'] as $order) {
    echo $order['order_id'], ' ', $order['order_status'], ' ', $order['payment_status'], ' ', $order['charges_totals']['grand_total'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' orders in total', PHP_EOL;

