get_order.code:
use WebCommander\Sdk\Resources\Orders\Orders;

$response = Orders::getOrder($client, 1043);

$order = $response->map['order'];
echo $order['order_id'], ' ', $order['order_status'], ' ', $order['payment_status'], ' ', $order['shipping_status'], PHP_EOL;
foreach ($order['items'] as $item) {
    echo $item['item_id'], ' ', $item['product_name'], ' x', $item['quantity'], ' ', $item['total_amount'], PHP_EOL;
}
echo $order['charges_totals']['grand_total'], ' total, ', $order['charges_totals']['due'], ' due', PHP_EOL;

